SELECT w.w_warehouse_name, cd.cd_gender, SUM(ss.ss_net_paid_inc_tax) AS total_paid, SUM(cr.cr_refunded_cash) AS total_refunded, SUM(ss.ss_net_paid_inc_tax) - SUM(cr.cr_refunded_cash) AS net_cash_flow, PERCENT_RANK() OVER (ORDER BY SUM(ss.ss_net_paid_inc_tax) DESC) AS sales_percentile, CASE WHEN SUM(ss.ss_net_paid_inc_tax) > 50000 THEN 'Top Performer' ELSE 'Average Performer' END AS performance_category FROM warehouse w LEFT JOIN catalog_returns cr ON cr.cr_warehouse_sk = w.w_warehouse_sk LEFT JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk LEFT JOIN store_sales ss ON ss.ss_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_return_amount IS NOT NULL GROUP BY w.w_warehouse_name, cd.cd_gender ORDER BY net_cash_flow DESC LIMIT 12
